.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #2d3039;
}

.sidebar-header {
    padding: 16px 20px;
    border-bottom: 1px solid #2d3039;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 20px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #2d3039;
}

.channel-item.active {
    background: #3b4252;
    border-left: 3px solid #5b9bd5;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #e0e0e0;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 12px;
    right: 16px;
    background: #5b9bd5;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.chat-main.thread-open {
    max-width: 55%;
}

.main-header {
    padding: 16px 24px;
    border-bottom: 1px solid #e5e7eb;
    flex-shrink: 0;
}

.main-header h2 {
    margin: 0;
    font-size: 1.2rem;
    color: #1a1a1a;
}

.main-header p {
